//! Golden tests. Fixtures are generated by tools/make_golden.py from the Python reference (misleading_slope.py).
use terrain_core::*;
use std::fs;

fn fixture() -> (Grid, Vec<(f32, f32, Vec<f32>, f32)>) {
    let txt = fs::read_to_string(concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures/golden.txt")).expect("run tools/make_golden.py");
    let mut it = txt.split_whitespace();
    let w: usize = it.next().unwrap().parse().unwrap();
    let h: usize = it.next().unwrap().parse().unwrap();
    let cell: f32 = it.next().unwrap().parse().unwrap();
    let z: Vec<f32> = (0..w * h).map(|_| it.next().unwrap().parse().unwrap()).collect();
    let ncases: usize = it.next().unwrap().parse().unwrap();
    let mut cases = vec![];
    for _ in 0..ncases {
        let el: f32 = it.next().unwrap().parse().unwrap();
        let az: f32 = it.next().unwrap().parse().unwrap();
        let share: f32 = it.next().unwrap().parse().unwrap(); // python looks-flat share, band 15, tol 0.10, whole grid
        let s: Vec<f32> = (0..w * h).map(|_| it.next().unwrap().parse().unwrap()).collect();
        cases.push((el, az, s, share));
    }
    (Grid::new(w, h, cell, z), cases)
}

#[test]
fn lambert_and_share_match_python() {
    let (g, cases) = fixture();
    assert!(!cases.is_empty());
    for (el, az, expect, py_share) in cases {
        let mut max = 0f32;
        for r in 0..g.h { for c in 0..g.w {
            max = max.max((g.lambert(c, r, el, az) - expect[r * g.w + c]).abs());
        }}
        assert!(max < 1e-4, "lambert el {el} az {az}: max diff {max}");
        let s = looks_flat(&g, (0, g.h, 0, g.w), 15.0, el, az, 0.10, 0, 1.0);
        match s.looks_flat_share() {
            Some(v) => assert!((v - py_share).abs() < 1e-3, "share el {el} az {az}: rust {v} python {py_share}"),
            None => assert!(py_share < 0.0, "python had steep pixels but rust found none"),
        }
    }
}

#[test]
fn wall_shadow_length() {
    let (w, h) = (120usize, 40usize);
    let mut z = vec![0f32; w * h];
    for r in 0..h { for c in 80..82 { z[r * w + c] = 5.0; } }
    let g = Grid::new(w, h, 1.0, z);
    let n = (0..80).filter(|&c| g.in_shadow(c, 20, 20.0, 90.0, 400, 60.0)).count() as f32;
    let exp = 5.0 / 20f32.to_radians().tan();
    assert!((n - exp).abs() <= 2.0, "shadow {n} m vs expected {exp} m");
    assert!(!g.in_shadow(100, 20, 20.0, 90.0, 400, 60.0)); // sun side of the wall is lit
}

#[test]
fn cross_sun_slope_looks_flat() {
    let (w, h) = (120usize, 120usize);
    let z: Vec<f32> = (0..h).flat_map(|_| (0..w).map(|c| -(25f32.to_radians().tan()) * c as f32)).collect();
    let g = Grid::new(w, h, 1.0, z);
    let b = g.lambert(60, 60, 30.0, 180.0);
    let darker = 1.0 - b / 30f32.to_radians().sin();
    assert!((darker - 0.094).abs() < 0.01, "darker {darker}");
    let s = looks_flat(&g, (10, 110, 10, 110), 15.0, 30.0, 180.0, 0.10, 0, 1.0);
    assert_eq!(s.looks_flat_share(), Some(1.0));
    let s = looks_flat(&g, (10, 110, 10, 110), 15.0, 30.0, 90.0, 0.10, 0, 1.0); // sun faces the slope
    assert_eq!(s.looks_flat_share(), Some(0.0));
}
